 for en,zh,loc,note in [('Kin-pack Declaration','亲族宣言','385 B0025','洛根正式承认鲁斯血脉子战团的宣言'),('Jarldom','酋长连','385 B0043','狼矛战团的大连称谓，沿用现稿'),('High Jarl','高酋长','385 B0047','狼矛必要时推选的最高统帅，沿现稿'),('Grimwolves','冷狼','385 B0051','特定狼矛猎手称谓'),('wyrd','命数','385 B0051','太空野狼命运观，不同于灵能异人'),('Oathbound','誓约者','385 B0066','共同宣誓组成小队的狼矛成员'),('First-slain','初殁者','385 B0068','在不屈远征战死的鲁斯血脉灰盾'),('Helix Adept','螺旋医疗员','385 B0112','渗透者专职医护，非正式药剂师'),('Trondek Witch-Breaker','特隆德克·破巫者','385 B0108','witch不指特定性别，原女巫终结者'),('Irik Stianolf','伊里克·斯蒂安诺夫','385 B0010','沿用现稿')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿',loc,note])+'\n')
